async function inst(id){const n=await figma.getNodeByIdAsync(id);return n.createInstance();}
async function comp(name){const n=await figma.getNodeByIdAsync('219:2');return n.findOne(x=>x.type==='COMPONENT'&&x.name===name);}
function T(chars,size,color,opts={}){const t=figma.createText();t.fontName={family:opts.font||'Tenor Sans',style:opts.style||'Regular'};t.characters=chars;t.fontSize=size;t.fills=S(color||BLACK);if(opts.ls!==undefined)t.letterSpacing={unit:'PIXELS',value:opts.ls};if(opts.w!==undefined)t.resize(opts.w,t.height);if(opts.align)t.textAlignHorizontal=opts.align;if(opts.lh)t.lineHeight={unit:'PIXELS',value:opts.lh};return t;}
function recolor(node,color){const c=HEX(color);node.findAll(n=>{if('strokes'in n&&n.strokes&&n.strokes.length)n.strokes=n.strokes.map(s=>({...s,color:c}));if('fills'in n&&Array.isArray(n.fills)&&n.fills.length)n.fills=n.fills.map(f=>f.type==='SOLID'?{...f,color:c}:f);return false;});}
async function imgHash(id){const n=await figma.getNodeByIdAsync(id);const bytes=await n.exportAsync({format:'PNG',constraint:{type:'SCALE',value:2}});return figma.createImage(bytes).hash;}
function rect(parent,x,y,w,h,color,rad=0){const r=figma.createRectangle();r.resize(w,h);r.x=x;r.y=y;r.fills=S(color);if(rad)r.cornerRadius=rad;parent.appendChild(r);return r;}
