const dest=page.findOne(x=>x.type==='FRAME'&&x.name==='06_Product_Detail').id;
let n=0;
f04.findAll(x=>x.type==='INSTANCE'&&x.name.startsWith('Card_')).forEach(x=>{try{x.reactions=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',navigation:'NAVIGATE',destinationId:dest,transition:{type:'SMART_ANIMATE',duration:0.3,easing:{type:'EASE_OUT'}}}]}];n++;}catch(e){}});
const stats={};
for(const fn of ['01_Home','04_Search_Results','05_Category_Grid','08_Collection_Detail']){const f=page.findOne(x=>x.type==='FRAME'&&x.name===fn);stats[fn]=f.findAll(x=>x.reactions&&x.reactions.length).length;}
return '04 linked='+n+' stats='+JSON.stringify(stats);

const page=await figma.getNodeByIdAsync('219:2');
const frames=page.children.filter(c=>c.type==='FRAME').map(c=>c.name);
const comps=page.children.filter(c=>c.type==='COMPONENT').map(c=>c.name);
const ref=await figma.getNodeByIdAsync('0:1');
const leaked=ref.children.filter(c=>c.name.startsWith('OF /')).map(c=>c.name);
const refFrames=ref.children.filter(c=>c.type==='FRAME').length;
return JSON.stringify({frames,comps,leaked,refFrames});

const page=await figma.getNodeByIdAsync('219:2');
let removed=0;
for(const c of page.children.slice()){if(c.type==='FRAME'&&c.name==='Frame'){c.remove();removed++;}}
const ref=await figma.getNodeByIdAsync('0:1');
let moved=0;
for(const c of ref.children.slice()){if(c.name==='OF / Chip'){c.remove();moved++;}}
return 'removed stray frames='+removed+' removed leaked chips='+moved;

const page=await figma.getNodeByIdAsync('219:2');
const comps=page.children.filter(c=>c.type==='COMPONENT').map(c=>c.name);
const frames=page.children.filter(c=>c.type==='FRAME').map(c=>c.name+'@'+Math.round(c.x)+','+Math.round(c.y));
return JSON.stringify({comps,frames});
